import{_ as i,C as l,o,c as m,a2 as a,j as n,G as r}from"./chunks/framework.BgSoyxN5.js";const T=JSON.parse('{"title":"Рыночный режим: в каких условиях вы сейчас, а не что только что произошло | TickerForge","description":"Пять названных состояний рынка, которые считаются одинаково каждую неделю и записываются при каждой смене. На что отвечает чтение режима — и почему новостная лента на этот вопрос не отвечает.","frontmatter":{"title":"Рыночный режим: в каких условиях вы сейчас, а не что только что произошло | TickerForge","description":"Пять названных состояний рынка, которые считаются одинаково каждую неделю и записываются при каждой смене. На что отвечает чтение режима — и почему новостная лента на этот вопрос не отвечает.","aside":false,"locale":"ru","alternateLocales":{"en":"/market-intelligence/market-regime","ru":"/ru/market-intelligence/market-regime"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/market-intelligence/market-regime.md","filePath":"ru/market-intelligence/market-regime.md","lastUpdated":1788410450000}'),c={name:"ru/market-intelligence/market-regime.md"},p={class:"partners-wide"},d={class:"partners-post-gallery"};function g(h,e,k,_,u,f){const t=l("PartnerPostImage"),s=l("PartnerChannelCta");return o(),m("div",null,[e[0]||(e[0]=a('<h1 id="рыночныи-режим" tabindex="-1">Рыночный режим <a class="header-anchor" href="#рыночныи-режим" aria-label="Permalink to &quot;Рыночный режим&quot;">​</a></h1><p>Пять названных состояний — Паника, Защитный, Восстановление, Тренд, Эйфория. Одно из них верно прямо сейчас, и от того, какое именно, зависит, как читать всё остальное.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="/market-widget">Посмотреть текущий режим</a><a class="partners-button partners-button--secondary" href="#publish">Публиковать в своём канале</a></div><p class="partners-locale-switch"><a href="/market-intelligence/market-regime" hreflang="en">Read this page in English</a></p><p class="partners-backlink"><a href="/ru/market-intelligence/">Все чтения Market Intelligence</a> · <a href="/ru/market-intelligence/market-stress">Рыночный стресс</a> · <a href="/ru/market-intelligence/fear-and-greed">Fear &amp; Greed</a></p><h2 id="answers" tabindex="-1">На какой вопрос отвечает <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;На какой вопрос отвечает {#answers}&quot;">​</a></h2><p><strong>«Это падение — шум или подтверждение?»</strong></p><p>Одно и то же снижение на 1% означает противоположные вещи в разных условиях. В режиме Тренда это откат на рынке с широким участием. В Защитном — рынок делает ровно то, что делает хрупкий рынок. Заголовок такое различие провести не может: он про этот 1%, а не про условия вокруг него.</p><h2 id="why" tabindex="-1">Почему чтение состояния сильнее новостной ленты <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Почему чтение состояния сильнее новостной ленты {#why}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Это ряд, а не поток.</strong> Режим — одна метка, которая держится неделями. За «Защитный → Восстановление → Тренд» можно следить месяцами и видеть форму цикла. Лента каждое утро подсовывает новую тему и не связывает их между собой.</li><li><strong>Он меняется редко — и в этом смысл.</strong> В большинстве дней ответ «как вчера». Показатель, который скачет каждый день, измеряет не состояние, а шум.</li><li><strong>О смене сообщается отдельно.</strong> И дневной срез, и недельный пост всегда называют текущий режим — поэтому режим, который только что повернул, выглядит так же, как державшийся три недели. Отдельный алерт выходит только в те дни, когда смена действительно была: пример ниже.</li><li><strong>Всё записано.</strong> Каждое чтение сохраняется с датой. Никому не нужно верить каналу на слово насчёт того, что он говорил в прошлом месяце.</li><li><strong>Правило открыто.</strong> Кросс-активная панель тренда, макро-счёт, кросс-проверка по силе тренда — <a href="/methodology/decoding-market-regimes">метод описан</a>, и с ним можно спорить по существу.</li></ul></div><h2 id="example" tabindex="-1">Как выглядит пост <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Как выглядит пост {#example}&quot;">​</a></h2>',11)),n("div",p,[n("div",d,[r(t,{src:"/partners/examples/daily-market-regime-sample.png",alt:"Пост TickerForge «Рыночный режим»: текущий режим, состояние акций, широта рынка и макро-слой риска",caption:"Регулярное чтение — режим, панель и за чем следить.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),r(t,{src:"/partners/examples/market-regime-state-change-sample.png",alt:"Алерт TickerForge «Смена рыночного режима»: переход, что он значит, смещение риска и план действий",caption:"Алерт о смене — выходит только в те недели, когда режим повернул.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"})])]),e[1]||(e[1]=a('<h2 id="method" tabindex="-1">Как это считается <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Как это считается {#method}&quot;">​</a></h2><p>Кросс-активная панель тренда по акциям, кредиту, ставкам, доллару и волатильности даёт макро-счёт; счёт отображается в один из пяти режимов и перепроверяется по силе тренда — чтобы один шатающийся вход не переключил метку в одиночку.</p><p>Полное описание: <a href="/methodology/decoding-market-regimes">Decoding Market Regimes</a>.</p><h2 id="publish" tabindex="-1">Два способа этим пользоваться <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;Два способа этим пользоваться {#publish}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Читать.</strong> Недельный пост о режиме и дневной срез выходят в публичном канале TickerForge, полная рыночная панель — в боте.</li><li><strong>Публиковать.</strong> Одобренный партнёр в одно нажатие получает тот же пост со своей отслеживаемой ссылкой, на английском или русском — включая алерт о смене, который кабинет отказывается генерировать в неделю, когда режим не менялся. Подробнее: <a href="/ru/partners/market-news">партнёры по рыночным новостям</a>.</li></ul></div>',5)),r(s),e[2]||(e[2]=a('<p>Режим — это контекст, а не сигнал. Он не говорит, что покупать, что продавать и когда. TickerForge — образовательное ПО для поддержки решений, не инвестиционная рекомендация.</p><h2 id="смежные-страницы" tabindex="-1">Смежные страницы <a class="header-anchor" href="#смежные-страницы" aria-label="Permalink to &quot;Смежные страницы&quot;">​</a></h2><ul><li><a href="/ru/market-intelligence/">Все чтения Market Intelligence</a></li><li><a href="/market-widget">Живой виджет рыночного режима</a></li><li><a href="/methodology/decoding-market-regimes">Методология рыночных режимов</a></li><li><a href="/ru/partners/market-news">Партнёрская программа по рыночным новостям</a></li></ul>',3))])}const P=i(c,[["render",g]]);export{T as __pageData,P as default};
